// Flags facilities whose names suggest a non-senior or non-residential service for their care category.
// Read-only. Input: the build export all_senior_living_complete.csv (generated by `npm run export-facilities`).
// Usage: node scripts/seo/category_name_check.mjs [path/to/all_senior_living_complete.csv]
// A name match is a lead for review, not proof of misclassification. Hospital-based nursing homes match legitimately.
import fs from 'node:fs';

const file = process.argv[2] || 'all_senior_living_complete.csv';
const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/).filter(Boolean);
const parse = (l) => { const o = []; let c = '', q = false; for (let i = 0; i < l.length; i++) { const ch = l[i]; if (q) { if (ch === '"') { if (l[i + 1] === '"') { c += '"'; i++; } else q = false; } else c += ch; } else if (ch === '"') q = true; else if (ch === ',') { o.push(c); c = ''; } else c += ch; } o.push(c); return o; };
const header = parse(lines[0]);
const col = (name) => header.indexOf(name);
const iName = col('name'), iCare = col('care_type'), iState = col('state_abbr');

const NON_SENIOR = /dialysis|renal|elementary|middle school|high school|\bschool\b|pediatric|children|\bkids\b|dental|dentist|imaging|radiology|urgent care|pharmacy|laborator|surgery|surgical|endoscopy|oncology|cancer center|cardiology|orthopedic|ambulatory|methadone|substance|family health center|medical arts|eye care|vision center/i;

const byCare = new Map();
for (const line of lines.slice(1)) {
  const r = parse(line);
  const care = r[iCare] || '(blank)';
  const b = byCare.get(care) || { total: 0, flagged: 0, byState: new Map(), examples: [] };
  b.total++;
  if (NON_SENIOR.test(r[iName] || '')) {
    b.flagged++;
    const st = r[iState] || '?';
    b.byState.set(st, (b.byState.get(st) || 0) + 1);
    if (b.examples.length < 5) b.examples.push(`${r[iName]} (${st})`);
  }
  byCare.set(care, b);
}
for (const [care, b] of byCare) {
  const states = [...b.byState].sort((a, c) => c[1] - a[1]).slice(0, 3).map(([s, n]) => `${s}:${n}`).join(' ');
  console.log(`${care.padEnd(28)} total=${b.total} flagged=${b.flagged} (${((100 * b.flagged) / b.total).toFixed(1)}%) top=${states} e.g. ${b.examples.join('; ')}`);
}
